    const weekly=document.createElement('div');weekly.className='setting-row';weekly.innerHTML='<span>Resumen semanal<small>Recibe una síntesis semanal de actividad</small></span><input class="toggle" type="checkbox">';card.append(weekly);
    const summary=document.createElement('div');summary.className='setting-row';summary.innerHTML='<span>Resumen ejecutivo<small>Incluir resumen al comienzo del informe</small></span><input class="toggle" type="checkbox" checked>';rows[0]?.after(summary);
