  async function hydrateProfile(){
    const {user,stats,sessions}=await api('profile');
    const name=`${user.nombre} ${user.apellidos}`.trim();const card=document.querySelector('.profile-card');if(!card)return;
    card.querySelector('.profile-big').textContent=(user.nombre||'L').slice(0,1).toUpperCase();card.querySelector('h2').textContent=name;card.querySelector('p').textContent=`${user.rol||'auditor'} · ${user.organizacion||'Cuenta personal'}`;
    const facts=card.querySelectorAll('.profile-fact b');if(facts[0])facts[0].textContent=prettyDate(user.creado_en);if(facts[1])facts[1].textContent=stats.analisis_realizados||0;if(facts[2])facts[2].textContent=stats.proyectos||0;if(facts[3])facts[3].textContent=prettyDate(user.ultimo_acceso);
    const fields=document.querySelectorAll('.profile-panels input[readonly]');if(fields[0])fields[0].value=user.nombre||'';if(fields[1])fields[1].value=user.apellidos||'';if(fields[2])fields[2].value=user.email||'';if(fields[3])fields[3].value=user.rol||'auditor';
    const session=document.querySelector('.profile-panels .setting-card:last-child .setting-row');if(session){const current=sessions?.[0];if(current){session.querySelector('span').childNodes[0].textContent=`${current.sistema||'Web'} · ${current.navegador||'Navegador'}`;session.querySelector('small').textContent=`${current.ciudad||'Ubicación no disponible'} · Último uso ${prettyDate(current.ultimo_uso)}`}else{session.querySelector('span').childNodes[0].textContent='Sin sesiones activas';session.querySelector('small').textContent=stats.ultimo_acceso?`Último acceso ${prettyDate(stats.ultimo_acceso)}`:'No hay sesiones registradas'}}
  }
  async function hydrate(key){
    if(!protectedRoutes.has(key))return;
    try{
      const me=await api('me');if(route()!==key)return;
      const avatar=document.querySelector('.avatar');if(avatar)avatar.textContent=(me.user.nombre||'L').slice(0,1).toUpperCase();
      if(key==='dashboard')await hydrateDashboard();if(key==='analysis')prepareAnalysis();if(key==='history')await hydrateHistory();if(key==='report')await hydrateReport();if(key==='settings'){prepareSettings();await hydrateSettings()}if(key==='profile')await hydrateProfile();
    }catch(error){if(error.status===401){go('login');return}showError(error)}
  }
  function clearPrivatePlaceholders(key){
    if(key==='dashboard'){
      document.querySelectorAll('.stat-value').forEach((node,i)=>{if(i<3)node.textContent='—'});
      const recent=[...document.querySelectorAll('.card')].find(card=>card.querySelector('h3')?.textContent==='Últimos análisis');
      const body=recent?.querySelector('tbody');if(body)body.innerHTML='<tr><td colspan="8" class="muted">Cargando tus análisis…</td></tr>';
    }
    if(key==='history'){const table=document.querySelector('#history-table');if(table)table.innerHTML='<p class="muted tiny" style="padding:18px">Cargando historial…</p>'}
    if(key==='report'){const list=document.querySelector('.report-list');if(list)list.innerHTML='<p class="muted tiny">Cargando informes…</p>';const detail=document.querySelector('.report-detail');if(detail)detail.innerHTML='<p class="muted">Cargando informe…</p>'}
    if(key==='settings'){document.querySelectorAll('.settings-grid .setting-card:first-child input').forEach(input=>{input.value=''});const connection=document.querySelector('.settings-grid .setting-card:nth-child(2) .pill');if(connection){connection.textContent='Sin configurar';connection.className='pill pill-orange'}}
    if(key==='profile'){const card=document.querySelector('.profile-card');if(card){card.querySelector('h2').textContent='Cargando…';card.querySelector('.profile-big').textContent='…';card.querySelectorAll('.profile-fact b').forEach(x=>x.textContent='—')}}
  }
  const baseRender=render;
  window.removeEventListener('hashchange',baseRender);
  render=function(){baseRender();const key=route();if(key==='signup')prepareSignup();if(protectedRoutes.has(key))clearPrivatePlaceholders(key);hydrate(key)};
  window.addEventListener('hashchange',render);
  app.addEventListener('click',e=>{
    if(route()!=='home')return;const link=e.target.closest('a[href^="#"]');if(!link)return;
    const targetId=link.getAttribute('href').slice(1);if(!targetId||targetId.startsWith('/'))return;
    const section=document.getElementById(targetId);if(section){e.preventDefault();history.replaceState(null,'',`#${targetId}`);section.scrollIntoView({behavior:'smooth',block:'start'})}
  },true);
  app.addEventListener('submit',async e=>{
    const form=e.target;
    if(!form.matches('form[data-form],#analysis-form'))return;
    e.preventDefault();e.stopImmediatePropagation();
    const button=form.querySelector('[type="submit"]');if(button){button.disabled=true;button.dataset.oldText=button.textContent;button.textContent='Guardando…'}
    try{
      if(form.dataset.form==='signup'){
        const fd=new FormData(form);if(fd.get('password')!==fd.get('confirm'))throw new Error('Las contraseñas no coinciden.');
        await api('register',{method:'POST',body:{name:fd.get('name'),surname:fd.get('surname'),email:fd.get('email'),password:fd.get('password')}});notify('Cuenta creada. Ya puedes empezar.');go('dashboard');
      } else if(form.dataset.form==='login'){
        const fd=new FormData(form);await api('login',{method:'POST',body:{email:fd.get('email'),password:fd.get('password')}});notify('Sesión iniciada.');go('dashboard');
      } else if(form.id==='analysis-form'){
        const checked=[...form.querySelectorAll('.module input:checked')];const names=checked.map(input=>input.closest('.module').dataset.module).filter(Boolean);
        const typeMap={Completo:'completo',Estático:'estatico','Dinámico':'dinamico'};
        const authorized=form.querySelector('input[type="checkbox"][required]')?.checked;
        await api('analysis',{method:'POST',body:{url:form.querySelector('#url').value,type:typeMap[form.querySelector('#scan-type').value]||'completo',modules:names,ai:form.querySelector('.form-section:nth-of-type(3) input[type="checkbox"]')?.checked,authorized}});
        notify('Solicitud guardada como pendiente.');go('history');
      }
    }catch(error){showError(error)}finally{if(button){button.disabled=false;button.textContent=button.dataset.oldText||button.textContent}}
  },true);
  app.addEventListener('click',async e=>{
    const target=e.target.closest('[data-action],[data-analysis-id]');if(!target)return;
    if(target.dataset.action==='notifications'){
      e.preventDefault();e.stopImmediatePropagation();notify('No hay un servicio de notificaciones conectado todavía.');
    } else if(target.dataset.action==='integration'){
      e.preventDefault();e.stopImmediatePropagation();notify('La integración requiere configurar primero sus credenciales.');
    } else if(target.dataset.action==='check-connection'){
      e.preventDefault();e.stopImmediatePropagation();notify('Configura el servicio bastión antes de probar la conexión.');
    } else if(target.dataset.action==='forgot'){
      e.preventDefault();e.stopImmediatePropagation();notify('La recuperación por correo requiere configurar el servicio de correo.');
    } else if(target.dataset.action==='logout'){
      e.preventDefault();e.stopImmediatePropagation();try{await api('logout',{method:'POST'});csrfToken='';go('home')}catch(error){showError(error)}
    } else if(target.dataset.action==='save-settings'){
      e.preventDefault();e.stopImmediatePropagation();
      const cards=document.querySelectorAll('.settings-grid .setting-card');const fields=cards[0]?.querySelectorAll('input,select')||[];const toggles=cards[3]?.querySelectorAll('.toggle')||[];
      try{await api('settings',{method:'POST',body:{name:fields[0]?.value,surname:fields[1]?.value,email:fields[2]?.value,timezone:fields[3]?.value,format:'md_pdf',ai:toggles[0]?.checked,summary:toggles[1]?.checked,notify:toggles[2]?.checked,critical:toggles[3]?.checked,weekly:toggles[4]?.checked}});notify('Ajustes guardados.')}catch(error){showError(error)}
    } else if(target.dataset.analysisId){
      sessionStorage.setItem('selectedAnalysis',target.dataset.analysisId);
      if(route()==='report'){e.preventDefault();e.stopImmediatePropagation();document.querySelectorAll('[data-analysis-id]').forEach(x=>x.classList.toggle('selected',x===target));loadReport(target.dataset.analysisId).catch(showError)}
    } else if(target.dataset.action==='export'){
      e.preventDefault();e.stopImmediatePropagation();exportLiveCSV();
    } else if(target.dataset.action==='markdown'&&selectedReport){
      e.preventDefault();e.stopImmediatePropagation();const a=selectedReport.analysis;const text=`# Informe ${a.codigo}\n\n- Sitio: ${a.objetivo}\n- Estado: ${stateLabel(a.estado)}\n- Fecha: ${prettyDate(a.creado_en)}\n\n${selectedReport.findings.map(x=>`## ${severityLabel(x.severidad)} — ${x.tipo}\n\n${x.explicacion_ia||x.evidencia}\n\n${x.correccion_ia||''}`).join('\n\n')}`;const blob=new Blob([text],{type:'text/markdown;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${a.codigo}.md`;link.click();URL.revokeObjectURL(link.href);
    } else if(target.dataset.action==='pdf'){
      e.preventDefault();e.stopImmediatePropagation();window.print();
    }
  },true);
  if(!location.hash)location.hash=paths.home;
  render();
